    fields.add(new UnionRecordField("union", Repetition.ZERO_OR_ONE, Arrays.asList(new RecordField[] { new SimpleRecordField("one", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("two", FieldType.INT, Repetition.EXACTLY_ONE) })));
    fields.add(new UnionRecordField("union present", Repetition.ZERO_OR_ONE, Arrays.asList(new RecordField[] { new SimpleRecordField("one", FieldType.STRING, Repetition.EXACTLY_ONE), new SimpleRecordField("two", FieldType.INT, Repetition.ZERO_OR_MORE) })));
