    FlowFile file1 = runner.getFlowFilesForRelationship(PutS3Object.REL_SUCCESS).get(0);
    Assert.assertEquals(StorageClass.ReducedRedundancy.toString(), file1.getAttribute(PutS3Object.S3_STORAGECLASS_ATTR_KEY));
