@Test
public void testAuditInvoked() {
    User user1 = new User.Builder().identifier("user-id-1").identity("user-1").build();
    AccessPolicy policy1 = new AccessPolicy.Builder().identifier("policy-id-1").resource("resource1").action(RequestAction.READ).addUser(user1.getIdentifier()).build();
    Set<AccessPolicy> policies = new LinkedHashSet<>();
    policies.add(policy1);
    Set<User> users = new LinkedHashSet<>();
    users.add(user1);
    final MockPolicyBasedAuthorizer mockAuthorizer = new MockPolicyBasedAuthorizer(new HashSet<>(), users, policies);
    AuthorizerConfigurationContext context = Mockito.mock(AuthorizerConfigurationContext.class);
    Authorizer authorizer = AuthorizerFactory.installIntegrityChecks(mockAuthorizer);
    authorizer.onConfigured(context);
    final AuthorizationRequest accessAttempt = new AuthorizationRequest.Builder().resource(new MockResource("resource1", "Resource 1")).identity("user-1").action(RequestAction.READ).accessAttempt(true).anonymous(false).build();
    final AuthorizationResult accessAttemptResult = authorizer.authorize(accessAttempt);
    assertTrue(Result.Approved.equals(accessAttemptResult.getResult()));
    assertTrue(mockAuthorizer.isAudited(accessAttempt));
    final AuthorizationRequest nonAccessAttempt = new AuthorizationRequest.Builder().resource(new MockResource("resource1", "Resource 1")).identity("user-1").accessAttempt(false).action(RequestAction.READ).anonymous(false).build();
    final AuthorizationResult nonAccessAttempResult = authorizer.authorize(nonAccessAttempt);
    assertTrue(Result.Approved.equals(nonAccessAttempResult.getResult()));
    assertFalse(mockAuthorizer.isAudited(nonAccessAttempt));
}

@Test
public void testGetTargetUriAndUris() {
    final RemoteProcessGroupDTO dto = new RemoteProcessGroupDTO();
    assertNull(dto.getTargetUri());
    dto.setTargetUris("http://node1:8080/nifi, http://node2:8080/nifi");
    assertEquals("If targetUris are set but targetUri is not, it should returns the first uru of the targetUris", "http://node1:8080/nifi", dto.getTargetUri());
    assertEquals("http://node1:8080/nifi, http://node2:8080/nifi", dto.getTargetUris());
    dto.setTargetUri("http://node3:9090/nifi");
    assertEquals("If both targetUri and targetUris are set, each returns its own values", "http://node3:9090/nifi", dto.getTargetUri());
    assertEquals("http://node1:8080/nifi, http://node2:8080/nifi", dto.getTargetUris());
    dto.setTargetUris(null);
    assertEquals("http://node3:9090/nifi", dto.getTargetUri());
    assertEquals("getTargetUris should return targetUri when it's not set", "http://node3:9090/nifi", dto.getTargetUris());
}

@Test
public void testProcessorLoadsNarResources() throws IOException, ClassNotFoundException {
    TemporaryFolder temporaryFolder = new TemporaryFolder();
    temporaryFolder.create();
    NiFiProperties properties = loadSpecifiedProperties("/conf/nifi.properties", NiFiProperties.COMPONENT_DOCS_DIRECTORY, temporaryFolder.getRoot().getAbsolutePath());
    final Bundle systemBundle = SystemBundle.create(properties);
    final ExtensionMapping mapping = NarUnpacker.unpackNars(properties, systemBundle);
    NarClassLoaders.getInstance().init(properties.getFrameworkWorkingDirectory(), properties.getExtensionsWorkingDirectory());
    ExtensionManager.discoverExtensions(systemBundle, NarClassLoaders.getInstance().getBundles());
    DocGenerator.generate(properties, mapping);
    final String extensionClassName = "org.apache.nifi.processors.WriteResourceToStream";
    final BundleCoordinate coordinate = mapping.getProcessorNames().get(extensionClassName).stream().findFirst().get();
    final String path = coordinate.getGroup() + "/" + coordinate.getId() + "/" + coordinate.getVersion() + "/" + extensionClassName;
    File processorDirectory = new File(temporaryFolder.getRoot(), path);
    File indexHtml = new File(processorDirectory, "index.html");
    Assert.assertTrue(indexHtml + " should have been generated", indexHtml.exists());
    String generatedHtml = FileUtils.readFileToString(indexHtml);
    Assert.assertNotNull(generatedHtml);
    Assert.assertTrue(generatedHtml.contains("This example processor loads a resource from the nar and writes it to the FlowFile content"));
    Assert.assertTrue(generatedHtml.contains("files that were successfully processed"));
    Assert.assertTrue(generatedHtml.contains("files that were not successfully processed"));
    Assert.assertTrue(generatedHtml.contains("resources"));
}

