    runner.enqueue(insertStatement, attributes);
    attributes.put("sql.args.1.type", String.valueOf(Types.INTEGER));
    attributes.put("sql.args.1.value", "7");
    attributes.put("sql.args.2.type", String.valueOf(Types.BIT));
